{
	return regmap_update_bits(rdev->regmap, RK801_POWER_SLP_EN_REG,
				  BIT(rdev->desc->id), BIT(rdev->desc->id));
}

static int rk801_set_suspend_disable(struct regulator_dev *rdev)
{
	return regmap_update_bits(rdev->regmap, RK801_POWER_SLP_EN_REG,
				  BIT(rdev->desc->id), 0);
}

