      return RK806_BUCK_VOLT_MIN1 +
             (selector - RK806_BUCK_SEL_END0) * RK806_BUCK_VOLT_STEP1;
    }
  else
    {
      return RK806_BUCK_VOLT_MAX1;
    }
}

