      rdev = regulator_register(desc, ops, priv);
      if (rdev == NULL)
        {
          _err("ERROR: failed to register %s\n", desc->name);
          failed = true;
        }
      else if (cfg->voltage_source == RK806_VOLTAGE_READBACK)
