/****************************************************************************
 * Name: rk806_read_reg
 *
 * Description:
 *   Read a single 8-bit register from the RK806 over I2C.
 *
 ****************************************************************************/

static int rk806_read_reg(FAR struct rk806_dev_s *priv, uint8_t reg,
                          FAR uint8_t *value)
{
  struct i2c_msg_s msg[2];
  uint8_t regbuf[1];
  int ret;

  regbuf[0] = reg;

  /* First message: write the 8-bit register address (no stop). */

  msg[0].frequency = priv->frequency;
  msg[0].addr = priv->addr;
  msg[0].flags = 0;
  msg[0].buffer = regbuf;
  msg[0].length = 1;

  /* Second message: read back one byte. */

  msg[1].frequency = priv->frequency;
  msg[1].addr = priv->addr;
  msg[1].flags = I2C_M_READ;
  msg[1].buffer = value;
  msg[1].length = 1;

  ret = I2C_TRANSFER(priv->i2c, msg, 2);

/* Read-only UNKNOWN operations: no enable, disable, or voltage-set callback,
 * and voltage reads report -ENODATA.  Used for the DDR rails, which are set
 * by external feedback resistors and must not be touched by NuttX.
 */

